#pragma once
#include <chrono>
#include <functional>
#include <vector>
extern void beginAllocationMonitoring() noexcept;
extern unsigned long endAllocationMonitoring() noexcept;
namespace functional {
inline void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
inline void config(Phobos67Processor& p,int channels,double sr,int block){juce::AudioProcessor::BusesLayout l;l.inputBuses.add(channels==1?juce::AudioChannelSet::mono():juce::AudioChannelSet::stereo());l.outputBuses=l.inputBuses;require(p.setBusesLayout(l),"Layout rejected");p.prepareToPlay(sr,block);}
inline void signal(juce::AudioBuffer<float>& b,int offset,float amplitude=.3f,double sr=48000){for(int ch=0;ch<b.getNumChannels();ch++)for(int j=0;j<b.getNumSamples();j++){double t=(offset+j)/sr;b.setSample(ch,j,amplitude*(float)(.7*std::sin(juce::MathConstants<double>::twoPi*(ch?431:997)*t)+.3*std::sin(juce::MathConstants<double>::twoPi*53*t)));}}
inline std::vector<float> render(Phobos67Processor& p,int frames=48000){juce::AudioBuffer<float> b(2,128);juce::MidiBuffer m;std::vector<float> out;out.reserve(frames*2);for(int pos=0;pos<frames;pos+=128){signal(b,pos);p.processBlock(b,m);for(int j=0;j<128&&pos+j<frames;j++)for(int ch=0;ch<2;ch++)out.push_back(b.getSample(ch,j));}return out;}
inline int run(){int pass=0,fail=0;auto test=[&](const char* name,std::function<void()> fn){try{fn();std::cout<<"PASS "<<name<<"\n";pass++;}catch(const std::exception& e){endAllocationMonitoring();std::cout<<"FAIL "<<name<<": "<<e.what()<<"\n";fail++;}};
 test("Inflator anti-denormal: nonzero rounding preserved; exact zero alternates",[]{Phobos67Processor p;p.prepareToPlay(48000,128);const float x=-.10800193250179291f,expected=-.16079288721084595f;for(int n=0;n<2;n++)require(DspProbeAccess::inflate(p,x,.5f,1.f,false,0,false)==expected,"Antidenormal altered nonzero rounding");require(DspProbeAccess::inflate(p,1e-18f,.5f,0.f,false,1,false)==1e-18f,"Tiny nonzero input was replaced");float a=DspProbeAccess::inflate(p,0,.5f,0.f,false,0,false),b=DspProbeAccess::inflate(p,0,.5f,0.f,false,0,false);require(a>0&&b<0&&std::abs(a-7e-15f)<1e-20f&&std::abs(a+b)<1e-20f,"Zero replacement differs");});
 test("Final Clip: 40 rate/channel/block combinations; Input/Output max; active automation",[]{
  int clipped=0;for(double sr:{44100.,48000.,96000.,192000.})for(int channels:{1,2})for(int bs:{1,17,128,512,1024}){Phobos67Processor p;for(auto id:{"input","output"})set(p,id,24);for(auto id:{"even","odd","effect"})set(p,id,100);set(p,"air",10);set(p,"sub",10);set(p,"clip",1);config(p,channels,sr,128);juce::AudioBuffer<float> b(channels,bs+13);juce::MidiBuffer m;
   for(int n=0;n<12;n++){set(p,"airFreq",n%4);set(p,"subFreq",(n+1)%4);signal(b,n*b.getNumSamples(),4,sr);p.processBlock(b,m);for(int ch=0;ch<channels;ch++)for(int j=0;j<b.getNumSamples();j++){float x=b.getSample(ch,j);require(std::isfinite(x),"Nonfinite Clip output");require(std::abs(x)<=1.f,"Sample exceeded 0 dBFS after Output");if(std::abs(x)==1)clipped++;}}
  }require(clipped>100,"Ceiling test never exercised clipping");std::cout<<"  Ceiling-hit samples="<<clipped<<"\n";
 });
 test("Clip OFF permits signal above 0 dBFS; no hidden auto output",[]{Phobos67Processor p;set(p,"clip",0);set(p,"output",24);p.prepareToPlay(48000,128);auto out=render(p);float peak=0;for(float x:out)peak=juce::jmax(peak,std::abs(x));require(peak>2,"Clip OFF still limits output");});
 test("Power and host bypass: exact 38-sample delay, stereo, variable block sizes",[]{Phobos67Processor a,b;set(a,"power",0);set(a,"input",24);set(a,"output",24);a.prepareToPlay(48000,128);b.prepareToPlay(48000,128);require(a.getLatencySamples()==38,"Unexpected latency");std::vector<std::vector<float>> input(2);juce::MidiBuffer m;int offset=0;
  for(int n:{1,17,256,9,513,128,64,1024}){juce::AudioBuffer<float> x(2,n),y(2,n);signal(x,offset,2);for(int ch=0;ch<2;ch++)for(int j=0;j<n;j++)input[ch].push_back(x.getSample(ch,j));y.makeCopyOf(x);a.processBlock(x,m);b.processBlockBypassed(y,m);for(int ch=0;ch<2;ch++)for(int j=0;j<n;j++){float expected=offset+j<38?0:input[ch][offset+j-38];require(x.getSample(ch,j)==expected,"Power bypass changed sample");require(y.getSample(ch,j)==expected,"Host bypass changed sample");}offset+=n;}
 });
 test("Host bypass meters follow audio instead of freezing",[]{Phobos67Processor p;p.prepareToPlay(48000,128);juce::AudioBuffer<float>b(2,128);juce::MidiBuffer m;for(int n=0;n<200;n++){signal(b,n*128,.25f);p.processBlockBypassed(b,m);}require(p.outPeak.load()>-25&&p.outPeak.load()<-10,"Host bypass peak meter is stale");require(p.outK12.load()>-20,"Host bypass RMS meter is stale");});
 test("K-12 calibration and peak calibration: -12 dBFS sine; decay on silence",[]{Phobos67Processor p;set(p,"clip",0);p.prepareToPlay(48000,128);juce::AudioBuffer<float>b(2,128);juce::MidiBuffer m;for(int n=0;n<2000;n++){for(int j=0;j<128;j++){float x=std::pow(10.f,-12.f/20)*std::sin(juce::MathConstants<double>::twoPi*1000*(n*128+j)/48000);b.setSample(0,j,x);b.setSample(1,j,x);}p.processBlock(b,m);}require(std::abs(p.inK12.load())<.03,"Input K-12 zero calibration error");require(std::abs(p.outK12.load())<.03,"Output K-12 zero calibration error");require(std::abs(p.inPeak.load()+12)<.01,"Input peak calibration error");require(std::abs(p.outPeak.load()+12)<.02,"Output peak calibration error");float old=p.outK12.load();for(int n=0;n<1200;n++){b.clear();p.processBlock(b,m);}require(p.outPeak.load()<-90,"Peak did not return to silence");require(p.outK12.load()<old-20,"RMS meter decay stuck");});
 test("Every visible audio control changes the signal; all four frequency selections work",[]{
  for(auto id:{"input","even","odd","air","sub","mid","side","effect","curve","output","airFreq","subFreq"}){Phobos67Processor a,b;for(auto* q:{&a,&b}){set(*q,"clip",0);set(*q,"output",-12);if(juce::String(id)=="curve")set(*q,"effect",80);if(juce::String(id)=="airFreq")set(*q,"air",10);if(juce::String(id)=="subFreq")set(*q,"sub",10);}float value=juce::String(id).contains("Freq")?3:juce::String(id)=="input"?6:juce::String(id)=="output"?0:juce::String(id)=="curve"?40:juce::String(id)=="air"||juce::String(id)=="sub"?10:80;set(b,id,value);a.prepareToPlay(48000,128);b.prepareToPlay(48000,128);auto x=render(a),y=render(b);double energy=0;for(size_t n=12000;n<x.size();n++){double d=x[n]-y[n];energy+=d*d;}require(energy>1e-8,(juce::String(id)+" has no audio effect").toRawUTF8());}
 });
 test("192 kHz Sub 60 Hz +10 dB: stable output over five seconds",[]{Phobos67Processor p;set(p,"clip",0);set(p,"subFreq",2);set(p,"sub",10);p.prepareToPlay(192000,128);juce::AudioBuffer<float>b(2,128);juce::MidiBuffer m;for(int n=0;n<7500;n++){signal(b,n*128,.05f,192000);p.processBlock(b,m);for(int ch=0;ch<2;ch++)for(int j=0;j<128;j++)require(std::isfinite(b.getSample(ch,j))&&std::abs(b.getSample(ch,j))<.3f,"Unstable low shelf");}});
 test("Mid/Side gain: pure-mid and pure-side signals, -20/+6/+20 dB, no opposite-component gain",[]{
  for(bool side:{false,true})for(float db:{-20.f,6.f,20.f}){Phobos67Processor a,b;for(auto* q:{&a,&b})set(*q,"clip",0);set(b,side?"side":"mid",db);set(b,side?"mid":"side",-13);a.prepareToPlay(48000,128);b.prepareToPlay(48000,128);juce::AudioBuffer<float>x(2,128),y(2,128);juce::MidiBuffer m;float gain=juce::Decibels::decibelsToGain(db);for(int n=0;n<100;n++){for(int j=0;j<128;j++){float v=.01f*std::sin(juce::MathConstants<double>::twoPi*997*(n*128+j)/48000);x.setSample(0,j,v);x.setSample(1,j,side?-v:v);}y.makeCopyOf(x);a.processBlock(x,m);b.processBlock(y,m);for(int ch=0;ch<2;ch++)for(int j=0;j<128;j++)if(n>20)require(std::abs(y.getSample(ch,j)-x.getSample(ch,j)*gain)<1e-6f,"Mid/Side matrix or gain differs");}}
 });
 test("Mono and Delta: equal-channel sum and latency-aligned difference",[]{
  Phobos67Processor normal,mono,delta,dry;for(auto* q:{&normal,&mono,&delta}){set(*q,"clip",0);set(*q,"even",25);set(*q,"effect",73);set(*q,"bandSplit",1);}set(mono,"mono",1);set(delta,"delta",1);set(dry,"power",0);for(auto* q:{&normal,&mono,&delta,&dry})q->prepareToPlay(48000,128);auto n=render(normal),m=render(mono),d=render(delta),b=render(dry);for(size_t i=0;i<n.size();i+=2){float expected=(n[i]+n[i+1])*.5f;require(m[i]==m[i+1]&&std::abs(m[i]-expected)<1e-7,"Mono sum differs");for(size_t ch=0;ch<2;ch++)require(std::abs(d[i+ch]-(n[i+ch]-b[i+ch]))<1e-7,"Delta is not processed minus delayed input");}
 });
 test("Stereo meters: independent L/R peaks and RMS, K-14 zero reference",[]{
  Phobos67Processor p;set(p,"clip",0);p.prepareToPlay(48000,128);juce::AudioBuffer<float>b(2,128);juce::MidiBuffer m;for(int n=0;n<3000;n++){for(int j=0;j<128;j++){float x=std::pow(10.f,-14.f/20)*std::sin(juce::MathConstants<double>::twoPi*1000*(n*128+j)/48000);b.setSample(0,j,x);b.setSample(1,j,x*.1f);}p.processBlock(b,m);}require(std::abs(p.inPeakLR[0].load()-p.inPeakLR[1].load()-20)<.01,"Input L/R peak not independent");require(std::abs(p.outPeakLR[0].load()-p.outPeakLR[1].load()-20)<.03,"Output L/R peak not independent");require(std::abs(p.inK12LR[0].load()+2)<.03,"K-14 zero calibration differs");require(std::abs(p.inK12LR[0].load()-p.inK12LR[1].load()-20)<.02,"L/R RMS not independent");
 });
 test("Band Split and Order change audio; Clip holds in all monitor/stage combinations",[]{
  Phobos67Processor direct,split,reverse;for(auto* q:{&direct,&split,&reverse}){set(*q,"clip",0);set(*q,"effect",90);set(*q,"even",50);set(*q,"odd",30);}set(split,"bandSplit",1);set(reverse,"reverseOrder",1);for(auto* q:{&direct,&split,&reverse})q->prepareToPlay(48000,128);auto a=render(direct),b=render(split),c=render(reverse);double eb=0,ec=0;for(size_t i=12000;i<a.size();i++){eb+=(a[i]-b[i])*(a[i]-b[i]);ec+=(a[i]-c[i])*(a[i]-c[i]);}require(eb>1e-6&&ec>1e-6,"Split/Order has no audio effect");
  for(int mode=0;mode<16;mode++){Phobos67Processor p;set(p,"input",24);set(p,"output",24);set(p,"effect",100);set(p,"odd",100);set(p,"bandSplit",(mode>>0)&1);set(p,"reverseOrder",(mode>>1)&1);set(p,"mono",(mode>>2)&1);set(p,"delta",(mode>>3)&1);p.prepareToPlay(192000,128);juce::AudioBuffer<float>x(2,257);juce::MidiBuffer midi;for(int n=0;n<100;n++){signal(x,n*257,4,192000);p.processBlock(x,midi);for(int ch=0;ch<2;ch++)for(int j=0;j<257;j++)require(std::isfinite(x.getSample(ch,j))&&std::abs(x.getSample(ch,j))<=1,"Clip escaped in Split/Order/Mono/Delta");}}
 });
 test("Full state round-trip and restored audio; malformed state rejected",[]{Phobos67Processor a,b;for(auto id:{"input","output"})set(a,id,-6);set(a,"even",37);set(a,"odd",63);set(a,"air",3);set(a,"sub",4);set(a,"airFreq",3);set(a,"subFreq",1);set(a,"mid",6);set(a,"side",-3);set(a,"effect",73);set(a,"curve",13);set(a,"bandSplit",1);set(a,"reverseOrder",1);set(a,"mono",1);set(a,"delta",1);set(a,"fobosOn",0);set(a,"inflateOn",0);juce::MemoryBlock state;a.getStateInformation(state);b.setStateInformation(state.getData(),(int)state.getSize());for(int n=0;n<a.getParameters().size();n++)require(a.getParameters()[n]->getValue()==b.getParameters()[n]->getValue(),"Parameter not restored");a.prepareToPlay(48000,128);b.prepareToPlay(48000,128);auto x=render(a),y=render(b);require(x==y,"Restored audio differs");char bad[32]{};float v=b.state.getRawParameterValue("effect")->load();b.setStateInformation(bad,32);require(b.state.getRawParameterValue("effect")->load()==v,"Malformed state changed controls");});
 test("Automation fuzz: all controls, 44.1/192 kHz, Clip ceiling and finite output",[]{std::mt19937 gen(67);std::uniform_real_distribution<float> rnd(0,1);for(double sr:{44100.,192000.}){Phobos67Processor p;p.prepareToPlay(sr,128);juce::AudioBuffer<float>b(2,257);juce::MidiBuffer m;for(int n=0;n<1000;n++){for(auto* parameter:p.getParameters())if(parameter!=p.state.getParameter("power"))parameter->setValueNotifyingHost(rnd(gen));set(p,"power",1);signal(b,n*257,4,sr);bool clip=p.state.getRawParameterValue("clip")->load()>.5f;p.processBlock(b,m);for(int ch=0;ch<2;ch++)for(int j=0;j<257;j++){float x=b.getSample(ch,j);require(std::isfinite(x),"Automation produced nonfinite sample");if(clip)require(std::abs(x)<=1,"Automation escaped final ceiling");}}}});
 test("No C++ heap allocation inside processBlock during parameter automation; timing",[]{Phobos67Processor p;p.prepareToPlay(48000,128);juce::AudioBuffer<float>b(2,128);juce::MidiBuffer m;unsigned long count=0;auto start=std::chrono::steady_clock::now();for(int n=0;n<2000;n++){set(p,"airFreq",n%4);set(p,"subFreq",(n+1)%4);set(p,"air",n%11);signal(b,n*128);beginAllocationMonitoring();p.processBlock(b,m);count+=endAllocationMonitoring();}double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();std::cout<<"  allocations="<<count<<"; elapsed including signal generation="<<ms<<" ms; audio duration=5333.33 ms\n";require(count==0,"Heap allocation on audio path");});
 test("Stereo isolation: one active channel does not leak into the silent channel",[]{Phobos67Processor p;set(p,"even",80);set(p,"odd",60);set(p,"effect",80);set(p,"sub",10);p.prepareToPlay(48000,128);juce::AudioBuffer<float>b(2,128);juce::MidiBuffer m;for(int n=0;n<1000;n++){signal(b,n*128);b.clear(1,0,128);p.processBlock(b,m);require(b.getMagnitude(1,0,128)<1e-12f,"Stereo crosstalk into silent channel");}});
 std::cout<<"FUNCTIONAL AUDIT: "<<pass<<" groups passed, "<<fail<<" failed\n";return fail?40:0;
}
}
